<?php
$myForms=count($coordProgrammeTypes)?safeRun($pdo,"SELECT * FROM progress_forms WHERE semester_id=? AND programme_type IN (".implode(',',array_fill(0,count($coordProgrammeTypes),'?')).") ORDER BY created_at DESC",array_merge([$currentSemesterId],$coordProgrammeTypes))->fetchAll():[];
