<div class="modal fade" id="editForm<?= (int)$f['id'] ?>" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><form method="post" enctype="multipart/form-data"><?= csrfField() ?><input type="hidden" name="action" value="edit_progress_form"><input type="hidden" name="progress_form_id" value="<?= (int)$f['id'] ?>"><div class="modal-header"><h6 class="modal-title">Edit Progress Form</h6><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label small fw-semibold">Title</label><input required name="title" class="form-control-fy w-100 mb-2" value="<?= e($f['title']) ?>"><label class="form-label small fw-semibold">Description</label><textarea name="description" class="form-control-fy w-100 mb-2" rows="3"><?= e($f['description']??'') ?></textarea><div class="row g-2"><div class="col-6"><label class="form-label small fw-semibold">Week</label><input type="number" min="1" name="week_number" class="form-control-fy w-100" value="<?= e((string)$f['week_number']) ?>"></div><div class="col-6"><label class="form-label small fw-semibold">Deadline</label><input type="date" name="deadline" class="form-control-fy w-100" value="<?= e($f['deadline']??'') ?>"></div></div><label class="form-label small fw-semibold mt-2">Replace template (optional)</label><input type="file" name="form_file" class="form-control-fy w-100"></div><div class="modal-footer"><button class="btn-fy-orange w-100">Update</button></div></form></div></div></div>
